## 🧩 Intermediate Project: "Task CLI"
> A mini todo/task manager in the terminal that lets you add, list, and delete tasks (stored in a local JSON file).

### 📁 Folder Structure
```
task-cli/
├── tasks.json
└── index.js
```

### 🧾 Step-by-step Code

**1. Initialize project**
```bash
mkdir task-cli
cd task-cli
npm init -y
npm install commander
```

**2. Create `tasks.json`**
```json
[]
```

**3. Create `index.js`**
```js
#!/usr/bin/env node
const { Command } = require('commander');
const fs = require('fs');
const program = new Command();

const TASK_FILE = 'tasks.json';

function loadTasks() {
  const data = fs.readFileSync(TASK_FILE, 'utf8');
  return JSON.parse(data);
}

function saveTasks(tasks) {
  fs.writeFileSync(TASK_FILE, JSON.stringify(tasks, null, 2));
}

program
  .name('task')
  .description('Simple CLI for managing tasks')
  .version('1.0.0');

program
  .command('add <task>')
  .description('Add a new task')
  .action((task) => {
    const tasks = loadTasks();
    tasks.push({ id: tasks.length + 1, text: task });
    saveTasks(tasks);
    console.log(`Added task: "${task}"`);
  });

program
  .command('list')
  .description('List all tasks')
  .action(() => {
    const tasks = loadTasks();
    if (tasks.length === 0) {
      console.log('No tasks found.');
    } else {
      console.log('Tasks:');
      tasks.forEach((t) => {
        console.log(`${t.id}. ${t.text}`);
      });
    }
  });

program
  .command('delete <id>')
  .description('Delete a task by its ID')
  .action((id) => {
    let tasks = loadTasks();
    const initialLength = tasks.length;
    tasks = tasks.filter(t => t.id !== parseInt(id));
    if (tasks.length === initialLength) {
      console.log(`Task with ID ${id} not found.`);
    } else {
      saveTasks(tasks.map((t, i) => ({ id: i + 1, text: t.text }))); // Reassign IDs
      console.log(`Deleted task with ID ${id}`);
    }
  });

program.parse(process.argv);
```

### ✅ Try it:
```bash
node index.js add "Study Commander.js"
node index.js list
node index.js delete 1
```

